import '../search/nav_search_notifier.dart';
import '../utils/strings.dart';
import 'drive_progress_provider.dart';
import 'sheet_state_provider.dart';

part 'nav_state_provider.g.dart';

@Riverpod(keepAlive: true)

LocationSettings locationSettings;

if (defaultTargetPlatform == TargetPlatform.android) {
  locationSettings = AndroidSettings(
    accuracy: LocationAccuracy.bestForNavigation, // Highest priority
    distanceFilter: 0,
    intervalDuration: const Duration(seconds: 1), // Force a 1Hz pulse
    forceLocationManager: true, // Bypass FusedLocationProviderClient 5s floor
    foregroundNotificationConfig: const ForegroundNotificationConfig(
      notificationTitle: 'Navigation active',
      notificationText: 'UKcheckpoints is tracking your location',
      enableWakeLock: true,
      setOngoing: true,
    ),
  );
} else if (defaultTargetPlatform == TargetPlatform.iOS) {
  locationSettings = AppleSettings(
    accuracy: LocationAccuracy.bestForNavigation,
    activityType:
        ActivityType.automotiveNavigation, // Tells iOS NOT to throttle
    distanceFilter: 0,
  );
} else {
  locationSettings = const LocationSettings(
    accuracy: LocationAccuracy.bestForNavigation,
    distanceFilter: 0,
  );
}

