// ── Private ───────────────────────────────────────────────────────────────

void _forwardLocation(Position pos) {
  final nav = _navigator;
  if (nav == null) {
    if (_kNavDebug) debugPrint("[NAV] navigator null — skip");
    return;
  }

  // HERE's map-matcher + interpolator REQUIRE a strictly increasing time.
  // Geolocator can emit duplicate/regressed timestamps on some Android devices,
  // which starves the interpolator and shows up as choppy/laggy marker motion.
  var ts = pos.timestamp.toUtc();
  final last = _lastLocTime;
  if (last != null && !ts.isAfter(last)) {
    ts = last.add(const Duration(milliseconds: 1));
  }
  _lastLocTime = ts;

  final location =
      Location.withCoordinates(GeoCoordinates(pos.latitude, pos.longitude))
        ..time = ts
        // Only pass real heading/speed. Geolocator returns 0.0/-1 for "unknown"
        // depending on platform; feeding a fake 0° bearing snaps the marker north.
        ..bearingInDegrees = pos.heading >= 0 ? pos.heading : null
        ..speedInMetersPerSecond = pos.speed >= 0 ? pos.speed : null
        ..horizontalAccuracyInMeters = pos.accuracy;

  nav.onLocationUpdated(location);

  if (_kNavDebug) {
    debugPrint(
      "[NAV] ${pos.latitude},${pos.longitude} "
      "hdg=${location.bearingInDegrees} spd=${location.speedInMetersPerSecond} t=$ts",
    );
  }
}

/// Delegates to the live VisualNavigator so callers get map-matched,
/// route-synced maneuver data instead of stale Route object data.
Maneuver? getManeuver(int index) => _navigator?.getManeuver(index);

