/// Stream of raw GPS fixes from [LocationManager.GPS_PROVIDER].
/// Android-only. Bypasses the fused provider's 5 s floor so the HERE
/// VisualNavigator interpolator gets ~1 Hz input.
Stream<Position> get rawGpsStream =>
    _channel.receiveBroadcastStream().map((raw) {
      final m = Map<String, dynamic>.from(raw as Map);
      return Position(
        latitude: (m['latitude'] as num).toDouble(),
        longitude: (m['longitude'] as num).toDouble(),
        timestamp: DateTime.fromMillisecondsSinceEpoch(
          (m['time'] as num).toInt(),
          isUtc: true,
