import 'dart:collection';
import 'dart:io' show Platform;

import 'package:here_sdk/core.dart';
import 'package:here_sdk/location.dart';
import 'package:here_sdk/src/sdk/core/engine/s_d_k_native_engine.dart';
import 'package:here_sdk/src/sdk/location/location_issue_listener_bridge.dart';
import 'package:here_sdk/src/sdk/location/location_status_listener_bridge.dart';
import 'package:here_sdk/src/sdk/location/location_update_listener_bridge.dart';

/// Handles location updates received according to the desired [LocationAccuracy] or [LocationOptions].
///
/// Each instance of this class will be using internally the same client providing the actual
/// location updates. For that reason, only one [LocationEngine] can be started at a time.
/// Multiple listeners can be attached, either to receive location updates, see [LocationListener],
/// status updates, see [LocationStatusListener] or location issue has occurred, see LocationIssueListener].
/// When a different [LocationAccuracy] or [LocationOptions] is
/// desired, the [LocationEngine] needs to be stopped and started again.
/// Note: starting the [LocationEngine] with [LocationOptions] is only supported in Android platforms.
class LocationEngine implements LocationEngineBase {
  /// Constructor of the LocationEngine.
  final LocationEngineBase _location;

  /// Location issue listener map for mapping listener to bridge.
  final LinkedHashMap<LocationIssueListener, LocationIssueListenerBridge> _locationIssueListeners =
      LinkedHashMap<LocationIssueListener, LocationIssueListenerBridge>();

  /// Location update listener map for mapping listener to bridge.
  final LinkedHashMap<LocationListener, LocationUpdateListenerBridge> _locationUpdateListeners =
      LinkedHashMap<LocationListener, LocationUpdateListenerBridge>();

  /// Location status listener map for mapping listener to bridge.
  final LinkedHashMap<LocationStatusListener, LocationStatusListenerBridge> _locationStatusListeners =
      LinkedHashMap<LocationStatusListener, LocationStatusListenerBridge>();

  LocationEngine() : this._withLocationEngineBase(LocationEngineBase.makeLocationEngineFromSharedSdkNativeEngine());

  LocationEngine.withSdkEngine(SDKNativeEngine sdkEngine)
      : this._withLocationEngineBase(LocationEngineBase.makeLocationEngine(sdkEngine));

  LocationEngine._withLocationEngineBase(this._location) {
    internalsetCallListenerFromMainThreadEnabled(false);
  }

  /// Starts the location engine with desired [LocationAccuracy].
  /// Make sure to call either [LocationEngine.confirmHEREPrivacyNoticeInclusion] or
  /// [LocationEngine.confirmHEREPrivacyNoticeException] beforehand.
  /// Returns [LocationEngineStatus.alreadyStarted] if [LocationEngine.startWithLocationAccuracy] or
  /// [LocationEngine.startWithLocationOptions] is called again without calling [LocationEngine.stop] in between.
  /// See [LocationEngineStatus] for other possible return values.
  LocationEngineStatus startWithLocationAccuracy(LocationAccuracy locationAccuracy) =>
      _location.startWithLocationAccuracy(locationAccuracy);

  /// On Android devices starts the location engine with desired [LocationOptions].
  /// Make sure to call either [LocationEngine.confirmHEREPrivacyNoticeInclusion] or
  /// [LocationEngine.confirmHEREPrivacyNoticeException] beforehand.
  /// Returns [LocationEngineStatus.alreadyStarted] if [LocationEngine.startWithLocationAccuracy] or
  /// [LocationEngine.startWithLocationOptions] is called again without calling [LocationEngine.stop] in between.
  /// See [LocationEngineStatus] for other possible return values.
  ///
  /// On iOS devices this is not supported and [LocationEngineStatus.notSupported] is returned.
  LocationEngineStatus startWithLocationOptions(LocationOptions locationOptions) =>
      _location.startWithLocationOptions(locationOptions);

  /// Reconfigures the location engine with desired LocationAccuracy.
  ///
  /// This method is a faster way to change location accuracy for already started
  /// location engine, than calling [LocationEngineBase.stop] and [LocationEngineBase.startWithLocationOptions] in sequence. Returns [LocationEngineStatus.notReady],
  /// if called for unstarted location engine.
  ///
  /// [locationAccuracy] Desired location accuracy. Requested accuracy is not guaranteed.
  ///
  /// Returns [LocationEngineStatus]. Engine status. Valid values are defined in [LocationEngineStatus]
  LocationEngineStatus updateLocationAccuracy(LocationAccuracy locationAccuracy) =>
      _location.updateLocationAccuracy(locationAccuracy);

  /// Reconfigures the location engine with desired LocationOptions.
  ///
  /// This method is a faster way to change location options for already started
  /// location engine, than calling [LocationEngineBase.stop] and [LocationEngineBase.startWithLocationOptions] in sequence. Returns [LocationEngineStatus.notReady],
  /// if called for unstarted location engine.
  /// This method variant is not currently supported on iOS platforms. Returns [LocationEngineStatus.notSupported] on platforms which this method variant is not supported.
  ///
  /// [locationOptions] Desired location options.
  ///
  /// Returns [LocationEngineStatus]. Engine status. Valid values are defined in [LocationEngineStatus]
  LocationEngineStatus updateLocationOptions(LocationOptions locationOptions) =>
      _location.updateLocationOptions(locationOptions);

  /// Stops the location engine.
  void stop() => _location.stop();

  /// On Android devices it is the responsibility of the application developer to ensure that
  /// the application user is informed about the collection of characteristic information
  /// regarding nearby mobile and Wi-Fi network signals. Additionally, a link to the related
  /// [HERE Privacy Notice](https://legal.here.com/here-network-positioning-via-sdk)
  /// must be made available to the user.
  ///
  /// This information can be included in the application's Terms & Conditions,
  /// or Privacy Policy, or otherwise made accessible to the user.
  ///
  /// **Example text for informing users about data collection:**
  /// > "This application uses location services provided by HERE Technologies.
  /// > To maintain, improve, and provide these services, HERE Technologies occasionally collects
  /// > characteristic information about nearby mobile and Wi-Fi network signals.
  /// > For more information, please refer to the HERE Privacy Notice at:
  /// > [https://legal.here.com/here-network-positioning-via-sdk](https://legal.here.com/here-network-positioning-via-sdk)"
  ///
  /// **Note:** By calling this method, the application developer confirms that
  /// this information is made available to the end user.
  ///
  /// For example, it is sufficient to inform users once that using the app requires
  /// acceptance of its terms (if any). Then, in the terms include the
  /// above mentioned data collection information and a link to the related HERE Privacy Notice.
  /// The user is not required to open the terms to acknowledge the data collection details.
  /// The "Positioning" example app on [GitHub](https://github.com/heremaps/here-sdk-examples)
  /// provides an example of this.
  ///
  /// When the above criteria are met, it is recommended to silently execute this
  /// method each time before starting the `LocationEngine`, as failure to do so
  /// will result in the engine being non-functional.
  ///
  /// Returns:
  /// - Immediately returns with [ConfirmationStatus.OK].
  ///
  /// On iOS devices this method does nothing and [ConfirmationStatus.ok] is returned.
  ConfirmationStatus confirmHEREPrivacyNoticeInclusion() =>
      _location.confirmHEREPrivacyNoticeInclusion();

  /// On Android devices by calling this method, the application developer confirms that they have received an
  /// exceptional permission from HERE in written form to **not** include a reference to the HERE
  /// Privacy Notice. As a result, the `LocationEngine` will not collect characteristic
  /// information about the nearby mobile and Wi-Fi network signals. However, the engine will still
  /// be fully functional and will deliver location updates when the exception can be confirmed.
  ///
  /// **Note:** This call should not involve user interaction and should be executed silently
  /// by the application before starting the `LocationEngine`.
  ///
  /// The permission for exceptional use will be verified asynchronously using your HERE SDK
  /// credentials. A missing permission will cause the `LocationEngine` to stop, and
  /// [LocationEngineStatus.PRIVACY_NOTICE_UNCONFIRMED] will be delivered to the
  /// `LocationStatusListener`.
  ///
  /// Returns:
  /// - A confirmation action status. Valid values are defined in [ConfirmationStatus].
  /// - A first-time call may result in [ConfirmationStatus.PENDING]. Ensure that the
  ///   `LocationStatusListener` is used to get notified if permission remains unconfirmed.
  ///
  /// On iOS devices this method does nothing and [ConfirmationStatus.ok] is returned.
  ConfirmationStatus confirmHEREPrivacyNoticeException() =>
      _location.confirmHEREPrivacyNoticeException();

  /// Adds a [LocationListener] to the engine to get notified when there is a new location update available.
  /// Supports more than one listener, instance is added only once.
  void addLocationListener(LocationListener listener) {
    if (!_locationUpdateListeners.containsKey(listener)) {
      _locationUpdateListeners[listener] = LocationUpdateListenerBridge(listener);
    }
    _location.addLocationListener(_locationUpdateListeners[listener]!);
  }

  /// Removes a [LocationListener] from the engine.
  void removeLocationListener(LocationListener listener) {
    LocationUpdateListenerBridge? bridge = _locationUpdateListeners.remove(listener);
    if (bridge == null) {
      return;
    }
    _location.removeLocationListener(bridge);
  }

  /// Adds a [LocationStatusListener] to the engine to get notified when there is a an important status change.
  /// Supports more than one listener, instance is added only once.
  void addLocationStatusListener(LocationStatusListener listener) {
    if (!_locationStatusListeners.containsKey(listener)) {
      _locationStatusListeners[listener] = LocationStatusListenerBridge(listener);
    }
    _location.addLocationStatusListener(_locationStatusListeners[listener]!);
  }

  /// Removes a [LocationStatusListener] from the engine.
  void removeLocationStatusListener(LocationStatusListener listener) {
    LocationStatusListenerBridge? bridge = _locationStatusListeners.remove(listener);
    if (bridge == null) {
      return;
    }
    _location.removeLocationStatusListener(bridge);
  }

  /// Adds a [LocationIssueListener] to the engine to get notified when a location issue has occurred
  /// Supports more than one listener, instance is added only once.
  void addLocationIssueListener(LocationIssueListener listener) {
    if (!_locationIssueListeners.containsKey(listener)) {
      _locationIssueListeners[listener] = LocationIssueListenerBridge(listener);
    }
    _location.addLocationIssueListener(_locationIssueListeners[listener]!);
  }

  /// Removes a [LocationIssueListener] from the engine.
  void removeLocationIssueListener(LocationIssueListener listener) {
    LocationIssueListenerBridge? bridge = _locationIssueListeners.remove(listener);
    if (bridge == null) {
      return;
    }
    _location.removeLocationIssueListener(bridge);
  }

  /// On iOS devices this enables or disables application's background location updates.
  /// By default background location updates
  /// are enabled if application has background location capabilities.
  /// Set [allowed] to true to allow background location updates, or false to disable them.
  /// Returns [LocationEngineStatus.ok] if call succeeds. [LocationEngineStatus.notAllowed] if the application
  /// does not have background location capabilities enabled.
  ///
  /// On Android devices this is not supported and [LocationEngineStatus.notSupported] is returned.
  LocationEngineStatus setBackgroundLocationAllowed(bool allowed) {
    if (Platform.isIOS) {
      return _location.setBackgroundLocationAllowed(allowed);
    }
    return LocationEngineStatus.notSupported;
  }

  /// On iOS devices this checks if application's background location updates are enabled.
  /// Returns true if background location updates are allowed, false otherwise.
  ///
  /// On Android devices this is not supported and false is returned.
  bool getBackgroundLocationAllowed() {
    if (Platform.isIOS) {
      return _location.getBackgroundLocationAllowed();
    }
    return false;
  }

  /// On iOS devices this controls visibility of application's background location indicator.
  /// By default background location indicator
  /// is visible, if application has background location capabilities.
  /// Set [visible] to true to show background location indicator, or false to hide it.
  /// Returns [LocationEngineStatus.ok] if call succeeds and [LocationEngineStatus.notAllowed] if the application
  /// does not have background location capabilities enabled.
  ///
  /// On Android devices this is not supported and [LocationEngineStatus.notSupported] is returned.
  LocationEngineStatus setBackgroundLocationIndicatorVisible(bool visible) {
    if (Platform.isIOS) {
      return _location.setBackgroundLocationIndicatorVisible(visible);
    }
    return LocationEngineStatus.notSupported;
  }

  /// On iOS devices this checks if application's background location indicator is visible.
  /// Returns true if background location indicator is visible, false otherwise.
  ///
  /// On Android devices this is not supported and false is returned.
  bool getBackgroundLocationIndicatorVisible() {
    if (Platform.isIOS) {
      return _location.getBackgroundLocationIndicatorVisible();
    }
    return false;
  }

  /// On iOS devices this controls automatic pausing of location updates e.g.
  /// for improving device's battery life at times when
  /// location data is unlikely to change.
  /// By default automatic pausing of location updates is allowed.
  /// Set [allowed] to true to allow automatic pausing of location updates, or false to disable them.
  /// When calling this method then [LocationEngineStatus.ok] is returned.
  ///
  /// On Android devices this is not supported and [LocationEngineStatus.notSupported] is returned.
  LocationEngineStatus setPauseLocationUpdatesAutomatically(bool allowed) {
    if (Platform.isIOS) {
      return _location.setPauseLocationUpdatesAutomatically(allowed);
    }
    return LocationEngineStatus.notSupported;
  }

  /// On iOS devices this checks if automatic pausing of location updates is enabled.
  /// Returns true if automatic pausing of location updates is enabled, false otherwise.
  ///
  /// On Android devices this is not supported and false is returned.
  bool getPauseLocationUpdatesAutomatically() {
    if (Platform.isIOS) {
      return _location.getPauseLocationUpdatesAutomatically();
    }
    return false;
  }

  /// On Android devices this enables or disables saving of last known location so
  /// that it persists across application sessions.
  /// By default persistent saving across sessions is enabled.
  /// Set [persistent] to true to enable last known location to persist across application sessions, or false to disable it.
  /// When calling this method then [LocationEngineStatus.ok] is returned.
  ///
  /// On iOS devices this is not supported and the value is stored, by default, across sessions.
  /// When calling this method then [LocationEngineStatus.notSupported] is returned.
  LocationEngineStatus setLastKnownLocationPersistent(bool persistent)  {
    if (Platform.isAndroid) {
      return _location.setLastKnownLocationPersistent(persistent);
    }
    return LocationEngineStatus.notSupported;
  }

  /// The last known location obtained by the engine.
  /// [Location] is returned synchronously. [Location] object has a timestamp attribute,
  /// which reflects when data was obtained. If location was never obtained - null is returned.
  Location? get lastKnownLocation => _location.lastKnownLocation;

  // Checks if the engine is in started state.
  bool get isStarted => _location.isStarted;

  void internalsetCallListenerFromMainThreadEnabled(bool enabled) =>
      _location.internalsetCallListenerFromMainThreadEnabled(enabled);
}

