}

void _setupLocationIndicator(HereMapController controller) {
  _locationIndicator = LocationIndicator.withMapView(controller)
    ..locationIndicatorStyle = LocationIndicatorIndicatorStyle.pedestrian
    ..enable(controller);
}

// Called once from _onMapCreated when the map is already centered on the
// user's position. Sets _lastLocation so updateLocation won't trigger the
// fly animation on the next GPS update.
void setInitialLocation(GeoCoordinates coordinates) {
  _lastLocation = coordinates;
  _locationIndicator?.updateLocation(Location.withCoordinates(coordinates));
  _prefetchAroundLocation(coordinates);
}

void updateLocation(GeoCoordinates coordinates) {
  final isFirstLocation = _lastLocation == null;
  _lastLocation = coordinates;
  _locationIndicator?.updateLocation(Location.withCoordinates(coordinates));

  if (isFirstLocation) {
    focusOnUserLocation();
    _prefetchAroundLocation(coordinates);
  }
}

